def last_weekday_on_or_before(year, month, day, weekday_num):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_before_year(y):
        y -= 1
        return y * 365 + y // 4 - y // 100 + y // 400

    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def ordinal(y, m, d):
        days = days_before_year(y)
        for mo in range(1, m):
            days += 29 if (mo == 2 and is_leap(y)) else month_lengths[mo - 1]
        return days + d

    ordinal_day = ordinal(year, month, day)
    current_weekday = (ordinal_day - 1) % 7
    offset = (current_weekday - weekday_num) % 7
    return day - offset

